<x-layouts.store title="Payment receipts"><section class="mx-auto max-w-7xl px-6 py-16"><p class="uppercase tracking-[.25em] text-gold">Payment verification</p><h1 class="mt-3 text-4xl">DuitNow receipts</h1><div class="mt-5 flex gap-4"><a href="{{ route('admin.payment-receipts.index') }}">All</a><a href="?status=pending">Pending</a><a href="?status=approved">Approved</a><a href="?status=rejected">Rejected</a></div>@if(session('success'))<p class="mt-6 border border-gold/40 p-4 text-gold">{{ session('success') }}</p>@endif @if($receipts->isEmpty())<div class="mt-10 border border-cream/15 p-10 text-center text-cream/65">No payment receipts have been submitted yet.<br><span class="text-sm">A receipt appears here only after a customer uploads one from the DuitNow payment page.</span></div>@else<div class="mt-8 overflow-x-auto"><table class="w-full text-left"><thead class="text-gold"><tr><th class="p-3">Order</th><th>Customer</th><th>Total</th><th>Receipt</th><th>Submitted</th><th>Status</th><th></th></tr></thead><tbody>@foreach($receipts as $receipt)<tr class="border-t border-cream/15"><td class="p-3">{{ $receipt->order->order_number }}</td><td>{{ $receipt->order->customer_name }}<br><small>{{ $receipt->order->customer_email }} · {{ $receipt->order->customer_phone }}</small></td><td>RM {{ number_format($receipt->order->total,2) }}</td><td><a class="text-gold" href="{{ route('admin.payment-receipts.download',$receipt) }}">{{ $receipt->original_filename ?: 'Download' }}</a></td><td>{{ ($receipt->submitted_at ?? $receipt->created_at)->format('d M Y H:i') }}</td><td class="capitalize">{{ $receipt->status }}</td><td><a class="luxury-link" href="{{ route('admin.payment-receipts.show',$receipt) }}">View</a></td></tr>@endforeach</tbody></table></div>{{ $receipts->links() }}@endif</section></x-layouts.store>
